<script setup>
import {computed,ref,watch} from 'vue'
import Icon from '../Icon.vue'
import SocialLinks from './SocialLinks.vue'
const props=defineProps({profile:Object,catalogue:Object,member:Object,busy:Boolean,enrolling:Boolean})
const emit=defineEmits(['teacher','enroll','more'])
const tab=ref('classes'),query=ref(''),year=ref('All'),kind=ref('All')
watch(()=>props.profile.name,()=>{tab.value=props.profile.kind==='Institute'?'teachers':'classes';query.value='';year.value='All';kind.value='All'},{immediate:true})
const teachers=computed(()=>props.catalogue.teachers||[])
const classes=computed(()=>props.catalogue.classes||[])
const years=computed(()=>[...new Set(classes.value.map(c=>c.batch_year).filter(Boolean))].sort())
const kinds=computed(()=>[...new Set(classes.value.map(c=>c.class_kind).filter(Boolean))].sort())
const term=computed(()=>query.value.trim().toLowerCase())
const matchingTeachers=computed(()=>teachers.value.filter(t=>[t.display_name,t.curriculum,t.qualifications].join(' ').toLowerCase().includes(term.value)))
const matchingClasses=computed(()=>classes.value.filter(c=>(year.value==='All'||c.batch_year===year.value)&&(kind.value==='All'||c.class_kind===kind.value)&&[c.title,c.subject,c.teacher_name,c.grade].join(' ').toLowerCase().includes(term.value)))
const money=c=>c.fee_mode==='Free'?'Free class':Number.isFinite(Number(c.fee))&&c.fee!==null&&c.fee!==undefined?new Intl.NumberFormat('en-LK',{style:'currency',currency:c.currency||'LKR',maximumFractionDigits:0}).format(c.fee):'View class fees'
</script>
<template>
 <section class="provider-catalogue" aria-label="Provider courses and teachers">
  <div class="catalogue-heading"><div><span class="eyebrow">{{profile.kind==='Institute'?'YOUR NEXT CHAPTER STARTS HERE':'LEARN WITH '+profile.display_name.toUpperCase()}}</span><h2>{{profile.kind==='Institute'?'Find your teacher. Find your course.':'Choose your class.'}}</h2><p>{{profile.kind==='Institute'?'Explore our teaching community or go straight to the class you need.':'Theory, revision and paper classes, all in one place.'}}</p></div></div>
  <nav v-if="profile.kind==='Institute'" class="catalogue-tabs" aria-label="Browse institute"><button :aria-pressed="tab==='teachers'" @click="tab='teachers';query=''" ><Icon name="Users" :size="17"/>Teachers <span>{{catalogue.teacher_count??teachers.length}}</span></button><button :aria-pressed="tab==='classes'" @click="tab='classes';query=''" ><Icon name="BookOpen" :size="17"/>Courses & classes <span>{{catalogue.class_count??classes.length}}</span></button></nav>
  <div class="catalogue-filters"><label class="search"><Icon name="Search" :size="17"/><input v-model="query" :placeholder="tab==='teachers'?'Search teacher or subject':'Search class or subject'" :aria-label="tab==='teachers'?'Search institute teachers':'Search provider classes'"></label><template v-if="tab==='classes'"><label>Batch<select v-model="year"><option>All</option><option v-for="y in years" :key="y">{{y}}</option></select></label><label>Class type<select v-model="kind"><option>All</option><option v-for="k in kinds" :key="k">{{k}}</option></select></label></template></div>
  <div v-if="tab==='teachers'" class="provider-offering-grid">
   <article v-for="t in matchingTeachers" :key="t.name" class="provider-teacher-card"><div class="offering-cover"><img v-if="t.cover_image" :src="t.cover_image" alt="" loading="lazy"></div><div class="offering-body"><div class="offering-photo"><img v-if="t.profile_image" :src="t.profile_image" :alt="t.display_name" loading="lazy"><Icon v-else name="UserRound" :size="28"/></div><small v-if="t.lms_id" class="offering-id">{{t.lms_id}}</small><h3>{{t.display_name}}</h3><p class="teacher-qualification">{{t.qualifications}}</p><p class="teacher-subject">{{t.curriculum}}</p><p class="teacher-grades">{{t.grades}}</p><SocialLinks :profile="t" :show-empty="true"/><button class="button primary" @click="emit('teacher',t)">View teacher & classes <Icon name="ArrowRight" :size="16"/></button></div></article>
  </div>
  <div v-else class="provider-offering-grid">
   <article v-for="c in matchingClasses" :key="c.name" class="provider-class-card"><div class="offering-cover"><img v-if="c.cover_image" :src="c.cover_image" alt="" loading="lazy"></div><div class="offering-body"><div class="offering-tags"><span v-if="c.batch_year">{{c.batch_year}}</span><span>{{c.class_kind||'Class'}}</span><span v-if="c.teaching_medium">{{c.teaching_medium}}</span></div><h3>{{c.title}}</h3><p v-if="c.teacher_name" class="class-teacher-name"><Icon name="GraduationCap" :size="15"/>{{c.teacher_name}}</p><p class="class-schedule"><Icon name="CalendarDays" :size="15"/>{{c.schedule_label||'Schedule to be announced'}}</p><div class="offering-price"><strong>{{c.programme?'Included in course':money(c)}}</strong><small v-if="!c.programme&&c.billing_type==='Monthly'&&c.fee_mode!=='Free'">per month</small></div><p class="offering-fee-note">{{c.programme?'Enrol in the complete course to access its classes.':'Review your assigned fees before payment.'}}</p><button v-if="member.role==='Student'&&!profile.is_school" class="button primary" :disabled="enrolling||busy" @click="emit('enroll',c)">{{c.programme?'View course':c.enrolled?'Continue to class':'Join class'}}<Icon name="ArrowRight" :size="16"/></button><span v-else class="offering-fee-note">{{profile.is_school?'Contact the institute to enrol.':'Published class · available to students'}}</span></div></article>
  </div>
  <p v-if="!busy&&!(tab==='teachers'?matchingTeachers.length:matchingClasses.length)" class="catalogue-empty">{{query||year!=='All'||kind!=='All'?'No matches. Try another subject or clear your filters.':tab==='teachers'?'Teachers will appear here once their institute membership is approved.':'Published classes will appear here.'}}</p>
  <button v-if="catalogue.has_more" class="button subtle catalogue-more" :disabled="busy" @click="emit('more')">{{busy?'Loading…':'Load more teachers & classes'}}</button><p v-if="busy" role="status">Loading learning opportunities…</p>
 </section>
</template>
<style scoped>
.provider-catalogue{min-width:0;margin-top:28px}.catalogue-heading h2{font-size:26px;letter-spacing:-.7px;margin:9px 0}.catalogue-heading p{font-size:13px;color:var(--student-muted,#817489);line-height:1.7}.catalogue-tabs{display:flex;flex-direction:row;gap:8px;border-bottom:1px solid var(--student-border,#eee);margin:24px 0}.catalogue-tabs button{display:flex;width:auto;align-items:center;gap:9px;border:0;border-bottom:3px solid transparent;padding:15px 18px;background:none;font:inherit;font-size:13px;color:var(--student-ink,#4c365d);cursor:pointer}.catalogue-tabs button[aria-pressed=true]{color:var(--brand,#6128a5);border-color:var(--brand,#6128a5);font-weight:700}.catalogue-tabs span{padding:3px 7px;border-radius:7px;background:#9564bf13;font-size:10px}.catalogue-filters{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:22px 0}.catalogue-filters .search{flex:1;min-width:220px}.catalogue-filters>label:not(.search){display:flex;align-items:center;gap:8px;font-size:11px;color:var(--student-muted,#817489)}.catalogue-filters select{padding:10px;border:1px solid var(--student-border,#eee);border-radius:9px;background:var(--student-card,#fff);color:var(--student-ink,#473456);font:inherit}.provider-offering-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.provider-teacher-card,.provider-class-card{min-width:0;background:var(--student-card,#fff);border:1px solid var(--student-border,#e9e1ef);border-radius:20px;overflow:hidden;display:flex;flex-direction:column}.offering-cover{aspect-ratio:900/380;background:linear-gradient(130deg,#e9def8,#d8e6f1);overflow:hidden}.offering-cover img{display:block;width:100%;height:100%;object-fit:cover}.offering-body{padding:20px;display:flex;flex-direction:column;align-items:flex-start;flex:1}.offering-photo{width:76px;height:76px;border:4px solid var(--student-card,#fff);border-radius:50%;overflow:hidden;margin-top:-55px;z-index:1;background:#ebe2f5;display:grid;place-items:center}.offering-photo img{width:100%;height:100%;object-fit:cover;object-position:center 25%}.offering-id{font-size:9px;letter-spacing:.4px;color:var(--brand,#6128a5);margin:7px 0}.offering-body h3{font-size:18px;line-height:1.4;margin:8px 0;letter-spacing:-.3px}.offering-body p{font-size:11px;line-height:1.7;margin:5px 0}.teacher-qualification,.teacher-grades{color:var(--student-muted,#817489)}.teacher-subject{font-weight:700;color:var(--brand,#6128a5)}.offering-body :deep(.provider-social-links){margin:13px 0 20px;gap:5px}.offering-body :deep(.provider-social-links a),.offering-body :deep(.provider-social-links button){width:29px;min-height:30px;border-radius:8px}.offering-body :deep(.provider-social-links svg){width:16px;height:16px}.offering-body>.button{width:100%;margin-top:auto;justify-content:space-between;font-size:11px}.offering-tags{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:5px}.offering-tags span{font-size:9px;background:#9564bf10;color:var(--brand,#6128a5);padding:5px 8px;border-radius:6px}.class-teacher-name,.class-schedule{display:flex;gap:7px;align-items:flex-start;color:var(--student-muted,#817489)}.class-schedule svg,.class-teacher-name svg{flex-shrink:0;margin-top:2px}.offering-price{display:flex;align-items:baseline;gap:7px;margin:18px 0 0}.offering-price strong{font-size:17px}.offering-price small{font-size:10px;color:var(--student-muted,#817489)}.offering-body .offering-fee-note{font-size:9px;color:var(--student-muted,#817489);margin:6px 0 20px}.catalogue-empty{padding:35px;text-align:center;border:1px dashed var(--student-border,#ddd);border-radius:15px;color:var(--student-muted,#817489);font-size:13px}.catalogue-more{margin-top:20px}.catalogue-tabs button:focus-visible{outline:3px solid #b196d3;outline-offset:2px}@media(max-width:1150px){.provider-offering-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.provider-offering-grid{grid-template-columns:1fr}.catalogue-tabs button{font-size:11px;padding:12px 9px}.catalogue-heading h2{font-size:23px}}
</style>
